            this.Manager.Checkpoint("\"[TestInfo] The Open is preserved.\"");
            this.Manager.Comment("reaching state \'S2975\'");
            this.Manager.Comment("checking step \'return Disconnect\'");
            this.Manager.Comment("reaching state \'S2976\'");
            this.Manager.Comment("executing step \'call ReEstablishResilientOpenRequest(DiffUser)\'");
            this.IResilientHandleAdapterInstance.ReEstablishResilientOpenRequest(((Microsoft.Protocols.TestSuites.FileSharing.SMB2Model.Adapter.ModelUser)(1)));
            this.Manager.Comment("reaching state \'S2977\'");
            this.Manager.Comment("checking step \'return ReEstablishResilientOpenRequest\'");
            this.Manager.Comment("reaching state \'S2978\'");
            if ((this.Manager.ExpectEvent(this.QuiescenceTimeout, true, new ExpectedEvent(ResilientHandleDurableTestCase.ReEstablishResilientOpenResponseInfo, null, new ReEstablishResilientOpenResponseDelegate1(this.ResilientHandleDurableTestCaseS2967ReEstablishResilientOpenResponseChecker))) != -1)) {
